namespace ghidra.app.plugin.core.datamgr.actions;




using ghidra.program.model.data;
using ghidra.util;

/**
 * Confirmation dialog for merging two datatypes. The dialog displays the resulting datatype along
 * with the two being merged in a side by side view. Also displays any warning messages associated
 * with the merge.
 */
public class DataTypeMergeConfirmationDialog : AbstractDataTypeMergeDialog {

	private bool cancelled = false;

	public DataTypeMergeConfirmationDialog(DataType result, DataType mergeTo, DataType mergeFrom,
			List<string> warnings) : base("Merge Data Types?", result, mergeTo, mergeFrom, join(warnings))
    {
		setHelpLocation(new HelpLocation("DataTypeManagerPlugin", "Merge_Confirmation"));
		addApplyButton();
		addCancelButton();
	}

	/* @Override */
	protected void applyCallback() {
		close();
	}

	/* @Override */
	protected void cancelCallback() {
		cancelled = true;
		close();
	}

	public bool wasCancelled() {
		return cancelled;
	}

	/* @Override */
	protected string getMessageAreaTitle() {
		return "Warnings:";
	}

	private static string join(List<string> lines) {
		if (lines.isEmpty()) {
			return null;
		}
		return lines.stream().collect(Collectors.joining("\n"));
	}

}
